  Morocco:{ flag:"🇲🇦",color:"#C1272D",region:"Africa",description:"Chicago's North African community has brought the aromatic spice blends and slow-cooked tagines of Morocco to several excellent restaurants.",restaurants:[{name:"Shokran Moroccan Grill",neighborhood:"Avondale",description:"Family-owned by a family from Fez — tagines slow-cooked in traditional clay pots, couscous made from scratch on Fridays.",price:"$$",mustTry:"Lamb tagine with preserved lemon and olives",story:"Shokran means 'thank you' in Arabic — the owners say gratitude is the secret ingredient."},{name:"Kasbah",neighborhood:"Lincoln Park",description:"A Moroccan husband-and-wife team bringing the intimate experience of a riad dinner to Chicago's North Side.",price:"$$",mustTry:"Bastilla (sweet and savory pigeon pie)",story:"Bastilla is considered the crown jewel of Moroccan cuisine — rarely found authentic outside Morocco."}]},
